UPDATE vocabulary_card_generation_job_item
SET status = CASE id
    WHEN #{item.id} THEN #{item.status}
    END,
    vocabulary_id = CASE id
    WHEN #{item.id} THEN #{item.vocabularyId}
    END,
    attempt_count = CASE id
    WHEN #{item.id} THEN #{item.attemptCount}
    END,
    error_message = CASE id
    WHEN #{item.id} THEN #{item.errorMessage}
    END,
    update_time = #{list[0].updateTime},
    update_by = #{list[0].updateBy}
WHERE id IN
#{item.id}
